export const DISEASE_MAP = new Map(DISEASES.map((d) => [d.slug, d]));

export function getDisease(slug: string) {
  return DISEASE_MAP.get(slug);
}

export const DISEASE_SYSTEMS = Array.from(new Set(DISEASES.map((d) => d.system)));
export const DISEASE_CATEGORIES = Array.from(new Set(DISEASES.map((d) => d.category)));
